            th: "จำนวนเงินที่ได้รับการอนุมัติจะถูกกำหนดในระหว่างการสอบสวนของสารวัตรแรงงาน คุณจะต้องกรอกข้อมูลด้วยตนเองหลังจากตรวจสอบเครื่องคำนวณแล้ว และผลลัพธ์จากเครื่องคำนวณจะไม่ถูกโอนโดยอัตโนมัติ",
