            id: "Jumlah yang disetujui ditentukan selama penyelidikan inspektur ketenagakerjaan. Anda memasukkannya sendiri setelah memeriksa kalkulator, dan hasilnya tidak ditransfer secara otomatis oleh kalkulator.",
            si: "අනුමත මුදල තීරණය කරනු ලබන්නේ කම්කරු පරීක්ෂකවරයාගේ පරීක්ෂණය අතරතුරදීය. කැල්කියුලේටරය පරීක්ෂා කිරීමෙන් පසු ඔබ එය ඔබම ඇතුළත් කරන අතර කැල්කියුලේටරයේ ප්‍රතිඵලය ස්වයංක්‍රීයව මාරු නොවේ.",
            bn: "শ্রম পরিদর্শকের তদন্তের সময় অনুমোদিত পরিমাণ নির্ধারণ করা হয়। ক্যালকুলেটরটি পরীক্ষা করার পরে আপনি নিজেই এটি প্রবেশ করান এবং ক্যালকুলেটরের ফলাফল স্বয়ংক্রিয়ভাবে স্থানান্তরিত হয় না।",
            my: "အတည်ပြုထားသော ပမာဏကို အလုပ်သမားစစ်ဆေးရေးမှူး၏ စုံစမ်းစစ်ဆေးမှုအတွင်း ဆုံးဖြတ်ပါသည်။ ဂဏန်းတွက်စက်ကို စစ်ဆေးပြီးနောက် သင်ကိုယ်တိုင် ထည့်သွင်းရမည်ဖြစ်ပြီး ဂဏန်းတွက်စက်ရလဒ်ကို အလိုအလျောက် ထည့်သွင်းမည်မဟုတ်ပါ။",
            mn: "Баталгаажсан дүн нь хөдөлмөрийн байцаагчийн мөрдөн байцаалтын явцад тодорхойлогддог. Та тооцоолуурыг шалгасны дараа өөрөө оруулдаг бөгөөд тооцоолуурын үр дүн автоматаар шилждэггүй.",
            lo: "ຈຳນວນເງິນທີ່ໄດ້ຮັບການອະນຸມັດແມ່ນຖືກກຳນົດໃນລະຫວ່າງການສືບສວນຂອງເຈົ້າໜ້າທີ່ກວດກາແຮງງານ. ທ່ານຈະປ້ອນຂໍ້ມູນດ້ວຍຕົວທ່ານເອງຫຼັງຈາກກວດສອບເຄື່ອງຄິດໄລ່ແລ້ວ ແລະ ຜົນຂອງເຄື່ອງຄິດໄລ່ຈະບໍ່ຖືກໂອນໂດຍອັດຕະໂນມັດ.",
            tet:
                "Montante ne'ebé aprova sei determina durante investigasaun inspetór traballu nian. Ita sei hatama rasik hafoin verifika kalkuladór, no rezultadu kalkuladór nian la transfere automaticamente.",
            ne: "स्वीकृत रकम श्रम निरीक्षकको अनुसन्धानको क्रममा निर्धारण गरिन्छ। तपाईंले क्यालकुलेटर जाँच गरेपछि आफैं प्रविष्ट गर्नुहुन्छ, र क्यालकुलेटरको नतिजा स्वचालित रूपमा हस्तान्तरण हुँदैन।",
            zh: '确定金额由劳动监督官调查核定。请参考计算器结果后自行填写，计算器数值不会自动带入。',
            vi: 'Số tiền chính thức do thanh tra lao động xác định. Bạn tự nhập sau khi tham khảo máy tính lương, kết quả không tự động chuyển sang.',
            uz: "Tasdiqlangan miqdor mehnat inspektorining tekshiruvi davomida aniqlanadi. Siz uni kalkulyatorni tekshirgandan soʻng oʻzingiz kiritasiz va kalkulyator natijasi avtomatik ravishda oʻtkazilmaydi.",
          ),
        ),
