          body: L10nText(
            ko: '공인노무사법 제2조에 따라 서류 제출은 근로자 본인이 직접 해야 합니다. Local Bridge는 서식을 채워 보여드리는 것까지만 합니다.',
            en: 'Under the Certified Public Labor Attorney Act Article 2, the worker must submit the documents in person. Local Bridge only fills in and displays the form.',
            tr: "Yeminli Serbest Çalışma Avukatı Yasası Madde 2 uyarınca, işçi belgeleri şahsen sunmalıdır. Local Bridge yalnızca formu doldurur ve görüntüler.",
            tg: "Мутобиқи моддаи 2 Қонун дар бораи адвокати озоди меҳнат, коргарон бояд ҳуҷҷатҳоро шахсан пешниҳод кунанд. Local Bridge танҳо шаклро пур мекунад ва намоиш медиҳад.",
            fil:
                "Alinsunod sa Artikulo 2 ng Batas sa Certified Public Labor Attorney, ang mga manggagawa ay dapat personal na magsumite ng mga dokumento. Ang Local Bridge ay nagpupuno at nagpapakita lamang ng form.",
            ur: "حلف یافتہ فری لانس لیبر اٹارنی ایکٹ کے آرٹیکل 2 کے تحت، کارکنوں کو ذاتی طور پر دستاویزات جمع کرانی چاہئیں۔ Local Bridge صرف فارم پُر کرتا ہے اور اسے دکھاتا ہے۔",
            th: "ตามมาตรา 2 ของพระราชบัญญัติทนายความอิสระที่สาบานตน พนักงานจะต้องยื่นเอกสารด้วยตนเอง Local Bridge เพียงแค่กรอกและแสดงแบบฟอร์มเท่านั้น",
