            km: "យោងតាមមាត្រា 2 នៃច្បាប់មេធាវីការងារឯករាជ្យដែលបានស្បថ កម្មករត្រូវតែដាក់ឯកសារដោយផ្ទាល់។ Local Bridge គ្រាន់តែបំពេញ និងបង្ហាញទម្រង់ប៉ុណ្ណោះ។",
            id: "Berdasarkan Pasal 2 Undang-Undang Pengacara Ketenagakerjaan Swasta Bersumpah, pekerja harus menyerahkan dokumen secara langsung. Local Bridge hanya mengisi dan menampilkan formulir.",
            si: "සහතිකලත් කම්කරු නීතිඥ පනතේ 2 වගන්තියට අනුව, සේවකයින් විසින්ම ලේඛන ඉදිරිපත් කළ යුතුය. Local Bridge මඟින් පෝරමය පුරවා පෙන්වනු පමණි.",
            bn: "শপথপ্রাপ্ত ফ্রিল্যান্স অ্যাটর্নি আইনের ধারা 2 অনুসারে, শ্রমিকদের ব্যক্তিগতভাবে নথি জমা দিতে হবে। Local Bridge শুধুমাত্র ফর্মটি পূরণ করে এবং প্রদর্শন করে।",
            my: "ကျမ်းသစ္စာကျိန်ဆိုထားသော အလွတ်တန်းအလုပ်သမားရှေ့နေဥပဒေ ပုဒ်မ 2 အရ အလုပ်သမားများသည် စာရွက်စာတမ်းများကို လူကိုယ်တိုင် တင်ပြရမည်။ Local Bridge သည် ဖောင်ကိုဖြည့်ပြီး ပြသရုံသာဖြစ်သည်။",
            mn: "Тангараг өргөсөн хөдөлмөрийн хуульчийн тухай хуулийн 2-р зүйлд заасны дагуу ажилчид бичиг баримтыг биечлэн ирүүлэх ёстой. Local Bridge нь зөвхөн маягтыг бөглөж, харуулдаг.",
            lo: "ອີງຕາມມາດຕາ 2 ຂອງກົດໝາຍວ່າດ້ວຍທະນາຍຄວາມແຮງງານອິດສະຫຼະທີ່ໄດ້ສາບານຕົນແລ້ວ, ພະນັກງານຕ້ອງຍື່ນເອກະສານດ້ວຍຕົນເອງ. Local Bridge ພຽງແຕ່ຕື່ມແບບຟອມ ແລະ ສະແດງຜົນເທົ່ານັ້ນ.",
            tet:
                "Tuir Lei Advogadu Traballu Livre Juramentadu Artigu 2, traballadór sira tenke aprezenta dokumentu sira rasik. Local Bridge de'it prenxe no hatudu formuláriu.",
            ne: "शपथ लिएका स्वतन्त्र श्रम अधिवक्ता ऐनको धारा 2 अनुसार, कामदारले व्यक्तिगत रूपमा कागजातहरू पेश गर्नुपर्छ। लोकल ब्रिजले फारम भर्ने र देखाउने मात्र गर्छ।",
            zh: '根据《公认劳务士法》第2条，材料须由劳动者本人提交。Local Bridge 仅负责填写并展示表格。',
            vi: 'Theo Điều 2 Luật Luật sư lao động, người lao động phải tự nộp hồ sơ. Local Bridge chỉ điền và hiển thị biểu mẫu.',
            uz: "Sertifikatlangan davlat mehnat advokati toʻgʻrisidagi qonunning 2-moddasiga koʻra, ishchi hujjatlarni shaxsan topshirishi kerak. Local Bridge faqat formani toʻldiradi va koʻrsatadi.",
