                subtitle: L10nText(
                  ko: '임금체불 진정서를 실제로 접수하는 곳입니다. 통역 서비스를 미리 신청할 수 있고, 사업주와 분리 조사도 요청할 수 있습니다.',
                  en: 'This is where you actually file the unpaid-wage complaint. You can request interpreting in advance, and ask to be questioned separately from your employer.',
                  tr: "Ödenmemiş ücret şikayetini aslında buraya yaparsınız. Önceden tercüman talep edebilir ve işvereninizden ayrı olarak sorgulanmayı isteyebilirsiniz.",
                  tg: "Шумо дар асл шикояти музди меҳнати пардохтнашударо дар ин ҷо пешниҳод мекунед. Шумо метавонед пешакӣ тарҷумонро дархост кунед ва хоҳиш кунед, ки аз корфармои худ алоҳида пурсида шавед.",
                  fil:
                      "Dito mo talaga isusumite ang reklamo sa hindi nabayarang sahod. Maaari kang humiling ng interpreter nang maaga at humiling na interbyuhin nang hiwalay sa iyong employer.",
                  ur: "آپ دراصل یہاں غیر ادا شدہ اجرت کی شکایت درج کرتے ہیں۔ آپ پہلے سے مترجم کی درخواست کر سکتے ہیں اور اپنے آجر سے الگ سے پوچھ گچھ کرنے کی درخواست کر سکتے ہیں۔",
                  th: "คุณจะยื่นเรื่องร้องเรียนค่าจ้างค้างจ่ายที่นี่ คุณสามารถขอให้มีล่ามล่วงหน้าและขอให้สอบสวนแยกจากนายจ้างของคุณได้",
                  ky: "Төлөнбөгөн эмгек акы боюнча арызды чындыгында бул жерге бересиз. Алдын ала котормочуну сурап, жумуш берүүчүңүздөн өзүнчө суракка алынууну талап кылсаңыз болот.",
                  km: "អ្នកពិតជាដាក់ពាក្យបណ្ដឹងប្រាក់ឈ្នួលមិនទាន់បានបង់នៅទីនេះ។ អ្នកអាចស្នើសុំអ្នកបកប្រែជាមុន ហើយស្នើសុំឱ្យមានការសាកសួរដោយឡែកពីនិយោជករបស់អ្នក។",
                  id: "Anda sebenarnya mengajukan pengaduan upah yang belum dibayar di sini. Anda dapat meminta penerjemah sebelumnya dan meminta untuk diinterogasi secara terpisah dari atasan Anda.",
                  si: "ඔබ ඇත්ත වශයෙන්ම නොගෙවූ වැටුප් පැමිණිල්ල මෙහිදී සිදු කරයි. ඔබට කල්තියා පරිවර්තකයෙකු ඉල්ලා සිටිය හැකි අතර ඔබේ සේවායෝජකයාගෙන් වෙන්ව ප්‍රශ්න කිරීමට ඉල්ලා සිටිය හැක.",
                  bn: "আপনি আসলে এখানে অপ্রদত্ত মজুরি অভিযোগ দায়ের করেন। আপনি আগে থেকে একজন দোভাষীর জন্য অনুরোধ করতে পারেন এবং আপনার নিয়োগকর্তা থেকে আলাদাভাবে জিজ্ঞাসাবাদ করার জন্য অনুরোধ করতে পারেন।",
                  my: "မပေးရသေးသော လုပ်ခလစာ တိုင်ကြားစာကို ဤနေရာတွင် တင်ပြရမည်ဖြစ်သည်။ သင်သည် စကားပြန်တစ်ဦးကို ကြိုတင်တောင်းဆိုနိုင်ပြီး သင့်အလုပ်ရှင်နှင့် သီးခြားစစ်ဆေးမေးမြန်းရန် တောင်းဆိုနိုင်သည်။",
                  mn: "Та цалин хөлс төлөгдөөгүй тухай гомдлыг энд гаргадаг. Та орчуулагчийг урьдчилан хүсч, ажил олгогчоос тусад нь байцаалт авахыг хүсч болно.",
                  lo: "ທ່ານຈະຍື່ນຄຳຮ້ອງທຸກຄ່າຈ້າງທີ່ບໍ່ໄດ້ຮັບຕົວຈິງຢູ່ທີ່ນີ້. ທ່ານສາມາດຮ້ອງຂໍນາຍພາສາລ່ວງໜ້າໄດ້ ແລະ ຂໍໃຫ້ຖືກສອບສວນແຍກຕ່າງຫາກຈາກນາຍຈ້າງຂອງທ່ານ.",
                  tet:
                      "Ita halo keixa saláriu la selu iha ne'e. Ita bele husu atu iha intérprete antes no husu atu interroga ita mesak la'ós ho ita-nia empregadór.",
                  ne: "तपाईंले वास्तवमा भुक्तानी नगरिएको ज्यालाको गुनासो यहाँ गर्नुहुन्छ। तपाईंले पहिले नै दोभाषेको लागि अनुरोध गर्न सक्नुहुन्छ र आफ्नो रोजगारदाताबाट अलग सोधपुछ गर्न अनुरोध गर्न सक्नुहुन्छ।",
                  zh: '这是实际受理欠薪申诉书的地方。可事先申请翻译服务，也可要求与雇主分开调查。',
                  vi: 'Đây là nơi thực sự nộp đơn khiếu nại nợ lương. Có thể đăng ký phiên dịch trước và yêu cầu điều tra riêng với chủ.',
                  uz: "Bu yerda siz toʻlanmagan ish haqi shikoyatini topshirasiz. Siz oldindan tarjimonlikni soʻrashingiz va ish beruvchingizdan alohida soʻroq qilinishingizni soʻrashingiz mumkin.",
                ),
                phone: '1350',
                legalBasis: L10nText(
                  ko: '등록하신 근무지 주소를 기준으로 찾은 관할 기관입니다. 실제 관할은 접수 전 전화로 한 번 더 확인하는 것이 안전합니다.',
                  en: 'Based on your registered workplace address, this is the responsible office. Confirm by phone once more before filing, to be safe.',
                  tr: "Kayıtlı işyeri adresinize göre, sorumlu ofis burasıdır. Güvenli olmak için başvurmadan önce bir kez daha telefonla teyit edin.",
                  tg: "Мувофиқи суроғаи бақайдгирифтаи ҷои кори шумо, ин идораи масъул аст. Барои бехатарӣ, пеш аз муроҷиат бо телефон бори дигар тасдиқ кунед.",
                  fil:
                      "Batay sa iyong rehistradong address ng lugar ng trabaho, ito ang responsableng tanggapan. Upang makasiguro, kumpirmahin muli sa telepono bago mag-apply.",
                  ur: "آپ کے رجسٹرڈ کام کی جگہ کے پتے کے مطابق، یہ ذمہ دار دفتر ہے۔ محفوظ رہنے کے لیے، درخواست دینے سے پہلے ایک بار پھر فون پر تصدیق کر لیں۔",
                  th: "ตามที่อยู่สถานที่ทำงานที่ลงทะเบียนของคุณ สำนักงานที่รับผิดชอบคือที่นี่ เพื่อความปลอดภัย โปรดยืนยันทางโทรศัพท์อีกครั้งก่อนยื่นเรื่อง",
                  ky: "Катталган жумуш ордуңуздун дарегине ылайык, жооптуу кеңсе ушул жерде. Коопсуз болуу үчүн, кайрылуудан мурун телефон аркылуу дагы бир жолу ырастаңыз.",
                  km: "យោងតាមអាសយដ្ឋានកន្លែងធ្វើការដែលបានចុះបញ្ជីរបស់អ្នក ការិយាល័យទទួលខុសត្រូវគឺនៅទីនេះ។ ដើម្បីសុវត្ថិភាព សូមបញ្ជាក់ម្តងទៀតតាមទូរស័ព្ទមុនពេលដាក់ពាក្យ។",
                  id: "Berdasarkan alamat tempat kerja terdaftar Anda, ini adalah kantor yang bertanggung jawab. Untuk amannya, konfirmasikan sekali lagi melalui telepon sebelum mengajukan.",
                  si: "ඔබේ ලියාපදිංචි සේවා ස්ථාන ලිපිනය අනුව, වගකිවයුතු කාර්යාලය මෙයයි. ආරක්ෂිත වීමට, අයදුම් කිරීමට පෙර දුරකථනයෙන් තවත් වරක් තහවුරු කරන්න.",
                  bn: "আপনার নিবন্ধিত কর্মস্থলের ঠিকানা অনুযায়ী, এটিই দায়িত্বপ্রাপ্ত অফিস। নিরাপদ থাকার জন্য, আবেদন করার আগে একবার ফোন করে নিশ্চিত করুন।",
                  my: "သင်၏ မှတ်ပုံတင်ထားသော လုပ်ငန်းခွင်လိပ်စာအရ၊ ဤရုံးသည် တာဝန်ရှိသည်။ လုံခြုံမှုရှိစေရန်အတွက် လျှောက်ထားခြင်းမပြုမီ ဖုန်းဖြင့် တစ်ကြိမ်ထပ်မံ အတည်ပြုပါ။",
                  mn: "Бүртгэлтэй ажлын байрны хаягаар тань хариуцсан алба нь энэ байна. Аюулгүй байдлын үүднээс өргөдөл гаргахаасаа өмнө утсаар дахин нэг баталгаажуулна уу.",
                  lo: "ອີງຕາມທີ່ຢູ່ບ່ອນເຮັດວຽກທີ່ລົງທະບຽນຂອງທ່ານ, ຫ້ອງການທີ່ຮັບຜິດຊອບແມ່ນຢູ່ບ່ອນນີ້. ເພື່ອຄວາມປອດໄພ, ໃຫ້ຢືນຢັນອີກຄັ້ງທາງໂທລະສັບກ່ອນທີ່ຈະສະໝັກ.",
                  tet:
                      "Tuir ita-nia enderezu fatin servisu rejistradu, eskritóriu responsavel mak ida ne'e. Atu seguru, konfirma fila fali liuhusi telefone antes atu aplika.",
                  ne: "तपाईंको दर्ता गरिएको कार्यस्थलको ठेगाना अनुसार, जिम्मेवार कार्यालय यो हो। सुरक्षित हुनको लागि, आवेदन दिनु अघि एक पटक फेरि फोन गरेर पुष्टि गर्नुहोस्।",
                  zh: '根据您登记的工作地址，这是对应的管辖机关。提交前建议再电话确认一次管辖范围。',
                  vi: 'Dựa trên địa chỉ nơi làm việc đã đăng ký, đây là cơ quan phụ trách. Nên gọi điện xác nhận lại trước khi nộp.',
                  uz: "Roʻyxatdan oʻtgan ish joyingiz manziliga asoslanib, bu masʼul idora. Xavfsizlik uchun ariza topshirishdan oldin yana bir bor telefon orqali tasdiqlang.",
                ),
              ),
              NoticeBlock(
                tone: NoticeTone.amber,
                title: L10nText(
                  ko: '실제 관할은 접수 전 전화로 한 번 더 확인하세요',
                  en: 'Confirm the actual jurisdiction by phone once more before filing',
                  tr: "Başvurmadan önce gerçek yetki alanını bir kez daha telefonla teyit edin",
                  tg: "Пеш аз муроҷиат бори дигар қаламрави воқеиро бо телефон тасдиқ кунед",
                  fil:
                      "Kumpirmahin muli ang aktwal na hurisdiksyon sa telepono bago mag-apply",
