                  id: "Jika upah bulanan rata-rata Anda di bawah ambang batas yang ditentukan, mereka akan melakukan litigasi perdata dan prosedur eksekusi secara gratis. Periksa persyaratan pendapatan terlebih dahulu.",
                  si: "ඔබේ සාමාන්‍ය මාසික වැටුප නියමිත සීමාවට වඩා අඩු නම්, ඔවුන් සිවිල් නඩු සහ බලාත්මක කිරීමේ ක්‍රියා පටිපාටි නොමිලේ සිදු කරයි. පළමුව ආදායම් අවශ්‍යතාවය පරීක්ෂා කරන්න.",
                  bn: "যদি আপনার গড় মাসিক মজুরি নির্ধারিত সীমার নিচে হয়, তাহলে তারা বিনামূল্যে আইনি মামলা এবং প্রয়োগের প্রক্রিয়া পরিচালনা করে। প্রথমে আয়ের যোগ্যতা পরীক্ষা করুন।",
                  my: "သင်၏ ပျမ်းမျှလစဉ်လုပ်ခသည် သတ်မှတ်ထားသော ကန့်သတ်ချက်အောက်တွင်ရှိပါက၊ ၎င်းတို့သည် တရားစွဲဆိုမှုများနှင့် အမှုဆောင်လုပ်ငန်းများကို အခမဲ့ဆောင်ရွက်ပေးပါသည်။ ဝင်ငွေလိုအပ်ချက်ကို ဦးစွာစစ်ဆေးပါ။",
                  mn: "Хэрэв таны сарын дундаж цалин тогтоосон босгоос доогуур байвал тэд иргэний хэрэг, гүйцэтгэх ажиллагааг үнэ төлбөргүй явуулдаг. Эхлээд орлогын шаардлагыг шалгана уу.",
                  lo: "ຖ້າຄ່າຈ້າງສະເລ່ຍຕໍ່ເດືອນຂອງທ່ານຕໍ່າກວ່າເກນທີ່ກຳນົດໄວ້, ພວກເຂົາຈະດຳເນີນຄະດີທາງກົດໝາຍ ແລະ ຂັ້ນຕອນການບັງຄັບໃຊ້ໃຫ້ຟຣີ. ກວດສອບເງື່ອນໄຂລາຍໄດ້ກ່ອນ.",
                  tet:
                      "Se ita-nia saláriu médiu fulan-fulan menus husi limitasaun ne'ebé determina ona, sira sei halo prosesu legál no ezekusaun gratuita. Verifika uluk rekizitu rendimentu.",
                  ne: "यदि तपाईंको औसत मासिक ज्याला तोकिएको सीमाभन्दा कम छ भने, उनीहरूले निःशुल्क रूपमा कानुनी मुद्दाहरू र कार्यान्वयन प्रक्रियाहरू सञ्चालन गर्छन्। पहिले आयको शर्त जाँच गर्नुहोस्।",
                  zh: '若月平均工资低于一定标准，可免费协助民事诉讼与强制执行。请先确认收入条件。',
                  vi: 'Nếu lương bình quân tháng dưới ngưỡng quy định, họ hỗ trợ kiện dân sự và thi hành án miễn phí. Hãy kiểm tra điều kiện thu nhập trước.',
                  uz: "Agar sizning oʻrtacha oylik ish haqingiz belgilangan chegaradan past boʻlsa, ular fuqarolik daʼvolari va ijrosini bepul hal qilishadi. Avval daromad talabini tekshiring.",
                ),
                phone: '132',
                legalBasis: L10nText(
                  ko: '소득 요건에 맞으면 아래 기관에서 상담과 소송을 무료로 도와줍니다. 노무사·변호사를 개인적으로 선임할 수도 있습니다.',
                  en: 'If you meet the income requirement, the agency below offers free counselling and litigation help. You may also hire a labor attorney or lawyer privately.',
                  tr: "Gelir şartını karşılıyorsanız, aşağıdaki kurum ücretsiz danışmanlık ve dava yardımı sunar. Ayrıca özel olarak bir iş hukuku avukatı veya avukat tutabilirsiniz.",
                  tg: "Агар шумо ба шарти даромад мувофиқат кунед, муассисаи зерин машварат ва кӯмаки ройгонро пешниҳод мекунад. Шумо инчунин метавонед ба таври хусусӣ адвокати меҳнат ё ҳуқуқшиносро киро кунед.",
                  fil:
                      "Kung natutugunan mo ang kinakailangan sa kita, ang sumusunod na institusyon ay nag-aalok ng libreng konsultasyon at tulong sa paglilitis. Maaari ka ring kumuha ng labor attorney o abogado nang pribado.",
                  ur: "اگر آپ آمدنی کی شرط پوری کرتے ہیں، تو درج ذیل ادارہ مفت مشاورت اور مقدمے میں مدد فراہم کرتا ہے۔ آپ نجی طور پر ایک لیبر لاء اٹارنی یا وکیل بھی رکھ سکتے ہیں۔",
                  th: "หากคุณมีคุณสมบัติตามข้อกำหนดด้านรายได้ สถาบันด้านล่างนี้จะให้คำปรึกษาฟรีและความช่วยเหลือด้านการดำเนินคดี นอกจากนี้ คุณยังสามารถว่าจ้างทนายความด้านกฎหมายแรงงานหรือทนายความเป็นการส่วนตัวได้",
                  ky: "Эгерде сиз киреше талабына жооп берсеңиз, төмөнкү мекеме акысыз консультация жана соттук жардам көрсөтөт. Ошондой эле жеке эмгек укугу боюнча юристти же адвокатты жалдасаңыз болот.",
                  km: "ប្រសិនបើអ្នកបំពេញតាមលក្ខខណ្ឌប្រាក់ចំណូល ស្ថាប័នខាងក្រោមផ្តល់ការប្រឹក្សា និងជំនួយបណ្តឹងដោយឥតគិតថ្លៃ។ អ្នកក៏អាចជួលមេធាវីការងារ ឬមេធាវីដោយឯកជនផងដែរ។",
                  id: "Jika Anda memenuhi persyaratan pendapatan, lembaga berikut menawarkan konsultasi gratis dan bantuan litigasi. Anda juga dapat menyewa pengacara ketenagakerjaan atau pengacara secara pribadi.",
                  si: "ඔබ ආදායම් අවශ්‍යතාවය සපුරාලන්නේ නම්, පහත ආයතනය නොමිලේ උපදේශන සහ නඩු කටයුතු සඳහා සහාය ලබා දෙයි. ඔබට පෞද්ගලිකව කම්කරු නීතිඥයෙකු හෝ නීතිඥයෙකු ද කුලියට ගත හැකිය.",
                  bn: "যদি আপনি আয়ের যোগ্যতা পূরণ করেন, তাহলে নিম্নলিখিত সংস্থা বিনামূল্যে পরামর্শ এবং মামলায় সহায়তা প্রদান করে। আপনি ব্যক্তিগতভাবে একজন শ্রম আইন অ্যাটর্নি বা আইনজীবীও নিয়োগ করতে পারেন।",
                  my: "သင်သည် ဝင်ငွေလိုအပ်ချက်ကို ပြည့်မီပါက၊ အောက်ပါအဖွဲ့အစည်းသည် အခမဲ့အကြံဉာဏ်နှင့် တရားစွဲဆိုမှုအကူအညီကို ပေးပါသည်။ သင်သည် အလုပ်သမားဥပဒေရှေ့နေ သို့မဟုတ် ရှေ့နေတစ်ဦးကို သီးသန့်ငှားရမ်းနိုင်သည်။",
                  mn: "Хэрэв та орлогын шаардлагыг хангаж байвал дараах байгууллага үнэгүй зөвлөгөө, нэхэмжлэлийн тусламж үзүүлдэг. Та мөн хөдөлмөрийн хуульч эсвэл өмгөөлөгчийг хувийн журмаар хөлсөлж болно.",
                  lo: "ຖ້າທ່ານຕອບສະໜອງເງື່ອນໄຂລາຍໄດ້, ສະຖາບັນຕໍ່ໄປນີ້ໃຫ້ຄຳປຶກສາ ແລະ ການຊ່ວຍເຫຼືອດ້ານຄະດີຟຣີ. ນອກຈາກນີ້, ທ່ານຍັງສາມາດຈ້າງທະນາຍຄວາມແຮງງານ ຫຼື ທະນາຍຄວາມສ່ວນຕົວໄດ້.",
                  tet:
                      "Se ita kumpri rekizitu rendimentu, instituisaun tuir mai oferese konsulta gratuita no asisténsia prosesu. Ita mós bele kontrata advogadu traballu ka advogadu privadu.",
                  ne: "यदि तपाईंले आयको शर्त पूरा गर्नुहुन्छ भने, तलका संस्थाले निःशुल्क परामर्श र मुद्दामा सहायता प्रदान गर्छ। तपाईंले निजी रूपमा श्रम कानून अधिवक्ता वा वकिल पनि राख्न सक्नुहुन्छ।",
                  zh: '若符合收入条件，以下机构可提供免费咨询与诉讼协助，您也可自行聘请劳务士·律师。',
                  vi: 'Nếu đủ điều kiện thu nhập, cơ quan dưới đây hỗ trợ tư vấn và kiện tụng miễn phí. Bạn cũng có thể tự thuê luật sư.',
                  uz: "Agar siz daromad talabiga javob bersangiz, quyidagi agentlik bepul maslahat va sud ishlarida yordam taklif qiladi. Shuningdek, siz xususiy mehnat advokati yoki yuristni yollashingiz mumkin.",
                ),
              ),
              NoticeBlock(
                tone: NoticeTone.blue,
                title: L10nText(
                  ko: '마을노무사 제도도 있습니다',
                  en: "There is also a 'village labor attorney' scheme",
                  tr: "Ayrıca bir 'köy iş hukuku avukatı' sistemi de bulunmaktadır",
                  tg: "Инчунин системаи «адвокати меҳнати деҳа» мавҷуд аст",
                  fil: "Mayroon ding sistema ng 'village labor attorney'",
                  ur: "ایک 'گاؤں لیبر لاء اٹارنی' کا نظام بھی موجود ہے",
                  th: "นอกจากนี้ยังมีระบบ 'ทนายความด้านกฎหมายแรงงานประจำหมู่บ้าน' ด้วย",
                  ky: "Ошондой эле 'айылдык эмгек юристи' системасы да бар",
                  km: "ក៏មានប្រព័ន្ធ 'មេធាវីការងារភូមិ' ផងដែរ",
                  id: "Ada juga sistem 'pengacara ketenagakerjaan desa'",
                  si: "ගම්බද කම්කරු නීතිඥ ක්‍රමයක් ද ඇත",
                  bn: "একটি 'গ্রাম শ্রম আইন অ্যাটর্নি' ব্যবস্থাও রয়েছে",
                  my: "'ကျေးရွာအလုပ်သမားဥပဒေရှေ့နေ' စနစ်လည်း ရှိပါသည်။",
                  mn: "Мөн 'тосгоны хөдөлмөрийн хуульч' систем байдаг",
                  lo: "ນອກຈາກນີ້, ຍັງມີລະບົບ 'ທະນາຍຄວາມແຮງງານປະຈຳໝູ່ບ້ານ' ອີກດ້ວຍ.",
                  tet: "Iha mós sistema 'advogadu traballu aldeia'",
                  ne: "यसका अतिरिक्त, 'गाउँ श्रम कानून अधिवक्ता' प्रणाली पनि उपलब्ध छ।",
                  zh: '还有"村庄劳务士"制度',
                  vi: "Cũng có chương trình 'luật sư lao động cộng đồng'",
                  uz: "'Qishloq mehnat advokati' sxemasi ham mavjud",
                ),
                body: L10nText(
                  ko: '서류를 무료로 봐주는 제도입니다. 관할 고용센터나 지자체에 배치 여부를 문의해 보세요.',
                  en: 'A scheme that reviews your documents for free. Ask your local employment center or municipality if one is assigned.',
                  tr: "Belgelerinizi ücretsiz olarak inceleyen bir sistem. Yerel istihdam merkezinize veya belediyenize böyle bir avukat atanıp atanmadığını sorun.",
                  tg: "Системае, ки ҳуҷҷатҳои шуморо ройгон баррасӣ мекунад. Аз маркази шуғли маҳаллии худ ё ҳукумати шаҳр пурсед, ки оё чунин адвокат таъин шудааст.",
                  fil:
                      "Isang sistema na libreng sumusuri sa iyong mga dokumento. Tanungin ang iyong lokal na sentro ng trabaho o munisipalidad kung mayroong ganoong abogado na itinalaga.",
                  ur: "ایک ایسا نظام جو آپ کی دستاویزات کا مفت جائزہ لیتا ہے۔ اپنے مقامی روزگار مرکز یا میونسپلٹی سے پوچھیں کہ کیا ایسا کوئی اٹارنی مقرر کیا گیا ہے۔",
                  th: "ระบบที่ตรวจสอบเอกสารของคุณฟรี สอบถามสำนักงานจัดหางานในพื้นที่หรือเทศบาลของคุณว่ามีทนายความดังกล่าวประจำอยู่หรือไม่",
                  ky: "Документтериңизди акысыз карап чыгуучу система. Жергиликтүү жумуштуулук борборуңуздан же муниципалитетиңизден мындай юрист дайындалганбы же жокпу сураңыз.",
                  km: "ប្រព័ន្ធដែលពិនិត្យឯកសាររបស់អ្នកដោយឥតគិតថ្លៃ។ សួរមជ្ឈមណ្ឌលការងារក្នុងតំបន់ ឬសាលាក្រុងរបស់អ្នកថាតើមេធាវីបែបនេះត្រូវបានចាត់តាំងឬអត់។",
                  id: "Sistem yang meninjau dokumen Anda secara gratis. Tanyakan kepada pusat ketenagakerjaan setempat atau pemerintah kota Anda apakah pengacara seperti itu telah ditunjuk.",
                  si: "ඔබේ ලේඛන නොමිලේ සමාලෝචනය කරන පද්ධතියකි. ඔබේ ප්‍රාදේශීය රැකියා මධ්‍යස්ථානයෙන් හෝ නගර ශාලාවෙන් එවැනි නීතිඥයෙකු පත් කර ඇත්දැයි විමසන්න.",
                  bn: "একটি ব্যবস্থা যা বিনামূল্যে আপনার নথি পর্যালোচনা করে। আপনার স্থানীয় কর্মসংস্থান কেন্দ্র বা পৌরসভাকে জিজ্ঞাসা করুন যে এমন কোনো অ্যাটর্নি নিযুক্ত আছেন কিনা।",
                  my: "သင်၏စာရွက်စာတမ်းများကို အခမဲ့ပြန်လည်သုံးသပ်ပေးသည့်စနစ်။ သင်၏ဒေသခံအလုပ်အကိုင်စင်တာ သို့မဟုတ် မြို့တော်ခန်းမတွင် ထိုကဲ့သို့သောရှေ့နေတစ်ဦးကို ခန့်အပ်ထားခြင်းရှိမရှိ မေးမြန်းပါ။",
                  mn: "Таны бичиг баримтыг үнэ төлбөргүй хянадаг систем. Орон нутгийн хөдөлмөрийн төв эсвэл хотын захиргаанаас ийм хуульч томилогдсон эсэхийг асуугаарай.",
                  lo: "ລະບົບທີ່ກວດສອບເອກະສານຂອງທ່ານໂດຍບໍ່ເສຍຄ່າ. ສອບຖາມສູນການຈ້າງງານທ້ອງຖິ່ນ ຫຼື ເທດສະບານຂອງທ່ານວ່າໄດ້ມີການແຕ່ງຕັ້ງທະນາຍຄວາມດັ່ງກ່າວແລ້ວຫຼືບໍ່.",
                  tet:
                      "Sistema ida ne'ebé revé ita-nia dokumentu sira gratuita. Husu ba ita-nia sentru empregu lokál ka munisípiu se iha advogadu hanesan ne'e ne'ebé nomeia ona.",
                  ne: "तपाईंका कागजातहरू निःशुल्क रूपमा समीक्षा गर्ने प्रणाली। तपाईंको स्थानीय रोजगार केन्द्र वा नगरपालिकामा यस्तो अधिवक्ता नियुक्त गरिएको छ कि छैन भनेर सोध्नुहोस्।",
                  zh: '免费审阅材料的制度，可向当地就业中心或地方政府咨询是否有配置。',
                  vi: 'Chương trình xem giấy tờ miễn phí. Hãy hỏi trung tâm việc làm hoặc chính quyền địa phương.',
                  uz: "Hujjatlaringizni bepul koʻrib chiqadigan sxema. Mahalliy bandlik markazingiz yoki munitsipalitetingizdan biror kishi tayinlanganmi, soʻrang.",
                ),
