                  th: "หากนายจ้างไม่ตอบสนองหรือปฏิเสธ ให้ดำเนินการยื่นเรื่องออนไลน์หรือด้วยตนเอง",
                  ky: "Эгерде жумуш берүүчү жооп бербесе же баш тартса, онлайн же жеке өзү сотко кайрылууга өтүңүз.",
                  km: "ប្រសិនបើនិយោជកមិនឆ្លើយតប ឬបដិសេធ សូមបន្តទៅការប្តឹងតាមអ៊ីនធឺណិត ឬដោយផ្ទាល់។",
                  id: "Jika atasan tidak menanggapi atau menolak, lanjutkan untuk mengajukan gugatan secara online atau secara langsung.",
                  si: "සේවායෝජකයා ප්‍රතිචාර නොදක්වන්නේ නම් හෝ ප්‍රතික්ෂේප කරන්නේ නම්, මාර්ගගතව හෝ පෞද්ගලිකව නඩු පැවරීමට ඉදිරියට යන්න.",
                  bn: "যদি নিয়োগকর্তা সাড়া না দেন বা প্রত্যাখ্যান করেন, তাহলে অনলাইনে বা ব্যক্তিগতভাবে মামলা দায়ের করার দিকে এগিয়ে যান।",
                  my: "အလုပ်ရှင်က တုံ့ပြန်ခြင်းမရှိပါက သို့မဟုတ် ငြင်းဆိုပါက၊ အွန်လိုင်း သို့မဟုတ် လူကိုယ်တိုင် တရားစွဲဆိုရန် ဆက်လက်လုပ်ဆောင်ပါ။",
                  mn: "Хэрэв ажил олгогч хариу өгөхгүй эсвэл татгалзвал, онлайнаар эсвэл биечлэн нэхэмжлэл гаргах руу шилжинэ үү.",
                  lo: "ຖ້ານາຍຈ້າງບໍ່ຕອບ ຫຼື ປະຕິເສດ, ໃຫ້ດຳເນີນການຟ້ອງຮ້ອງທາງອອນລາຍ ຫຼື ດ້ວຍຕົນເອງ.",
                  tet:
