        lo: "ຢ່າເຊັນສັນຍາ ຫຼື ເອກະສານຍົກເວັ້ນໃດໆ ກ່ອນທີ່ເງິນຈະມາເຖິງຕົວຈິງ. ຖ້າທ່ານຂຽນ, ໃຫ້ລະບຸວັນທີຈ່າຍເງິນ ແລະ ຈໍານວນເງິນສຸດທິຫຼັງຫັກພາສີ, ແລະ ໃຫ້ລະບຸວ່າ: ເອກະສານຍົກເວັ້ນຈະຖືກຍື່ນເມື່ອໄດ້ຮັບເງິນແລ້ວ.",
