        th: "แจ้งสำนักงานแรงงานในภูมิภาคของคุณอย่างเป็นทางการและขอให้มีการแก้ไข คุณสามารถยื่นเรื่องร้องเรียนทางออนไลน์ ด้วยตนเอง ทางไปรษณีย์ หรือทางโทรสาร",
