        bn: "আপনার আঞ্চলিক শ্রম অফিসে আনুষ্ঠানিকভাবে অবহিত করুন এবং সমাধানের অনুরোধ করুন। আপনি অনলাইনে, ব্যক্তিগতভাবে, ডাকযোগে বা ফ্যাক্সের মাধ্যমে অভিযোগ দায়ের করতে পারেন।",
        my: "သင်၏ဒေသဆိုင်ရာ အလုပ်သမားရုံးသို့ တရားဝင်အကြောင်းကြားပြီး ဖြေရှင်းချက်တောင်းခံပါ။ အွန်လိုင်း၊ လူကိုယ်တိုင်၊ စာတိုက် သို့မဟုတ် ဖက်စ်ဖြင့် တိုင်ကြားစာတင်နိုင်ပါသည်။",
        mn: "Бүс нутгийн хөдөлмөрийн албанд албан ёсоор мэдэгдэж, шийдэл шаардана уу. Та онлайнаар, биечлэн, шуудангаар эсвэл факсаар гомдол гаргаж болно.",
        lo: "ແຈ້ງການຢ່າງເປັນທາງການຕໍ່ຫ້ອງການແຮງງານພາກພື້ນຂອງທ່ານ ແລະ ຮຽກຮ້ອງການແກ້ໄຂ. ທ່ານສາມາດຍື່ນຄໍາຮ້ອງທຸກທາງອອນລາຍ, ດ້ວຍຕົນເອງ, ທາງໄປສະນີ ຫຼື ທາງແຟັກ.",
        tet:
            "Ofisialmente informa imi-nia eskritóriu servisu rejionál no husu solusaun. Imi bele halo keixa liuhusi online, pesoalmente, korreiu ka faks.",
        ne: "आफ्नो क्षेत्रीय श्रम कार्यालयलाई आधिकारिक रूपमा जानकारी दिनुहोस् र समाधानको लागि अनुरोध गर्नुहोस्। तपाईं अनलाइन, व्यक्तिगत रूपमा, हुलाक वा फ्याक्स मार्फत उजुरी गर्न सक्नुहुन्छ।",
        zh: '向管辖地方雇佣劳动厅正式告知并请求解决。可在线·到访·邮寄·传真受理。',
        vi: 'Chính thức báo cho cơ quan lao động khu vực và yêu cầu giải quyết. Có thể nộp trực tuyến, trực tiếp, qua bưu điện hoặc fax.',
        uz: "Mintaqaviy mehnat idorangizni rasman xabardor qiling va hal qilishni soʻrang. Siz onlayn, shaxsan, pochta orqali yoki faks orqali ariza topshirishingiz mumkin.",
      ),
      documentsNeeded: L10nText(
        ko: '임금체불 진정서 / 신분증(외국인등록증)',
        en: 'Complaint form / ID (ARC)',
        tr: "Şikayet formu / Kimlik (ARC)",
        tg: "Шакли шикоят / Шаҳодатномаи шахсият (ARC)",
        fil: "Form ng reklamo / ID (ARC)",
