        km: "ទម្រង់ពាក្យបណ្តឹង / អត្តសញ្ញាណប័ណ្ណ (ARC)",
        id: "Formulir keluhan / ID (ARC)",
        si: "පැමිණිලි පත්‍රය / හැඳුනුම්පත (ARC)",
        bn: "অভিযোগ ফর্ম / আইডি (ARC)",
        my: "တိုင်ကြားစာပုံစံ / သက်သေခံကတ်ပြား (ARC)",
        mn: "Гомдлын маягт / Иргэний үнэмлэх (ARC)",
