      ),
      watchOutFor: L10nText(
        ko: '진정은 처벌보다 지급 지도가 목적입니다. 접수 후 대개 일주일 안에 근로감독관이 배정되고 2주 안팎으로 출석 조사가 잡힙니다. 형사 고소는 처벌을 구하는 별개 절차이므로 목적에 맞게 고르세요.',
        en: 'A complaint aims at getting you paid, not punishment. An inspector is usually assigned within a week and the meeting scheduled within about two weeks. A criminal complaint is a separate route seeking punishment — choose by your purpose.',
        tr: "Bir şikayet, ceza değil, size ödeme yapılmasını amaçlar. Bir müfettiş genellikle bir hafta içinde atanır ve toplantı yaklaşık iki hafta içinde planlanır. Bir ceza şikayeti, ceza arayan ayrı bir yoldur — amacınıza göre seçin.",
        tg: "Шикоят барои он аст, ки ба шумо пардохт карда шавад, на ҷазо. Одатан, дар давоми як ҳафта нозир таъин карда мешавад ва вохӯрӣ тақрибан дар давоми ду ҳафта ба нақша гирифта мешавад. Шикояти ҷиноӣ роҳи алоҳидаест, ки ҷазоро талаб мекунад — мувофиқи мақсади худ интихоб кунед.",
        fil:
            "Ang isang reklamo ay naglalayong mabayaran ka, hindi parusahan. Karaniwan, isang inspektor ang itatalaga sa loob ng isang linggo, at ang pulong ay nakaplano sa loob ng humigit-kumulang dalawang linggo. Ang isang criminal complaint ay isang hiwalay na paraan na naghahanap ng parusa — piliin ayon sa iyong layunin.",
        ur: "شکایت کا مقصد آپ کو ادائیگی کروانا ہے، نہ کہ سزا دلوانا۔ ایک انسپکٹر عام طور پر ایک ہفتے کے اندر مقرر کیا جاتا ہے، اور میٹنگ تقریباً دو ہفتوں میں طے کی جاتی ہے۔ ایک تعزیری شکایت ایک الگ راستہ ہے جو سزا کا متلاشی ہے — اپنے مقصد کے مطابق انتخاب کریں۔",
        th: "การร้องเรียนมีจุดประสงค์เพื่อให้คุณได้รับค่าจ้าง ไม่ใช่เพื่อลงโทษ โดยปกติแล้วเจ้าหน้าที่ตรวจสอบจะได้รับการแต่งตั้งภายในหนึ่งสัปดาห์ และการประชุมจะถูกกำหนดภายในประมาณสองสัปดาห์ การร้องเรียนเพื่อลงโทษเป็นอีกช่องทางหนึ่งที่มุ่งเน้นการลงโทษ — โปรดเลือกตามวัตถุประสงค์ของคุณ",
        ky: "Арыздын максаты – жазалоо эмес, сизге төлөмдү камсыз кылуу. Инспектор адатта бир жуманын ичинде дайындалат, ал эми жолугушуу болжол менен эки жуманын ичинде пландаштырылат. Жазалоо арызы – бул жазалоону көздөгөн өзүнчө жол – максатыңызга жараша тандаңыз.",
        km: "ពាក្យបណ្តឹងមានគោលបំណងឱ្យអ្នកទទួលបានការទូទាត់ មិនមែនជាការដាក់ទណ្ឌកម្មនោះទេ។ អធិការម្នាក់ជាធម្មតាត្រូវបានចាត់តាំងក្នុងរយៈពេលមួយសប្តាហ៍ ហើយការប្រជុំត្រូវបានកំណត់ពេលប្រហែលពីរ សប្តាហ៍។ ពាក្យបណ្តឹងព្រហ្មទណ្ឌគឺជាផ្លូវដាច់ដោយឡែកមួយដែលស្វែងរកការដាក់ទណ្ឌកម្ម — ជ្រើសរើសតាមគោលបំណងរបស់អ្នក។",
        id: "Keluhan bertujuan agar Anda dibayar, bukan hukuman. Seorang inspektur biasanya ditunjuk dalam waktu seminggu, dan pertemuan dijadwalkan dalam waktu sekitar dua minggu. Keluhan pidana adalah jalur terpisah yang mencari hukuman — pilih sesuai tujuan Anda.",
        si: "පැමිණිල්ලක් යනු දඬුවමක් නොව, ඔබට ගෙවීමක් ලබා දීම අරමුණු කරයි. පරීක්ෂකවරයෙකු සාමාන්‍යයෙන් සතියක් ඇතුළත පත් කරනු ලබන අතර රැස්වීම සති දෙකක් පමණ ඇතුළත සැලසුම් කරනු ලැබේ. දඬුවම් පැමිණිල්ලක් යනු දඬුවම් ඉල්ලා සිටින වෙනම මාර්ගයකි - ඔබේ අරමුණ අනුව තෝරා ගන්න.",
        bn: "একটি অভিযোগের উদ্দেশ্য হল আপনাকে অর্থ প্রদান করা, শাস্তি নয়। একজন পরিদর্শক সাধারণত এক সপ্তাহের মধ্যে নিযুক্ত হন এবং প্রায় দুই সপ্তাহের মধ্যে একটি মিটিং নির্ধারিত হয়। একটি ফৌজদারি অভিযোগ হল শাস্তি চাওয়ার একটি পৃথক উপায় — আপনার উদ্দেশ্য অনুযায়ী নির্বাচন করুন।",
        my: "တိုင်ကြားစာသည် ပြစ်ဒဏ်ပေးရန်မဟုတ်ဘဲ သင့်အား ငွေပေးချေရန် ရည်ရွယ်ပါသည်။ စစ်ဆေးရေးမှူးတစ်ဦးကို ပုံမှန်အားဖြင့် တစ်ပတ်အတွင်း ခန့်အပ်ပြီး အစည်းအဝေးကို နှစ်ပတ်ခန့်အတွင်း စီစဉ်ပါသည်။ ပြစ်ဒဏ်ပေးရန် တိုင်ကြားစာသည် ပြစ်ဒဏ်ပေးရန် ရည်ရွယ်သည့် သီးခြားနည်းလမ်းတစ်ခုဖြစ်သည် — သင်၏ရည်ရွယ်ချက်အလိုက် ရွေးချယ်ပါ။",
        mn: "Гомдол нь шийтгэл биш, харин танд төлбөр хийх зорилготой. Мөрдөн байцаагчийг ихэвчлэн долоо хоногийн дотор томилдог бөгөөд уулзалтыг хоёр долоо хоногийн дотор төлөвлөдөг. Эрүүгийн гомдол нь шийтгэл эрэлхийлдэг тусдаа зам юм - зорилгоосоо хамаарч сонгоно уу.",
        lo: "ການຮ້ອງທຸກມີຈຸດປະສົງເພື່ອໃຫ້ທ່ານໄດ້ຮັບຄ່າຈ້າງ, ບໍ່ແມ່ນການລົງໂທດ. ປົກກະຕິແລ້ວ, ຜູ້ກວດກາຈະຖືກແຕ່ງຕັ້ງພາຍໃນໜຶ່ງອາທິດ ແລະ ການປະຊຸມຈະຖືກກໍານົດພາຍໃນປະມານສອງອາທິດ. ການຮ້ອງທຸກທາງອາຍາແມ່ນເສັ້ນທາງແຍກຕ່າງຫາກທີ່ຊອກຫາການລົງໂທດ — ໃຫ້ເລືອກຕາມຈຸດປະສົງຂອງທ່ານ.",
        tet:
            "Keixa ida nia objetivu mak atu imi simu pagamentu, la'ós atu fó kastigu. Inspetór ida sei nomeia iha semana ida nia laran no enkontru sei planu iha semana rua nia laran. Keixa kriminál ida mak dalan seluk ne'ebé buka kastigu — hili tuir imi-nia objetivu.",
        ne: "उजुरीको उद्देश्य तपाईंलाई भुक्तानी दिलाउनु हो, दण्ड दिनु होइन। सामान्यतया एक हप्ता भित्र एक निरीक्षक नियुक्त गरिन्छ र बैठक लगभग दुई हप्ता भित्र तय गरिन्छ। दण्डको उजुरी दण्ड खोज्ने छुट्टै तरिका हो — आफ्नो उद्देश्य अनुसार छान्नुहोस्।",
        zh: '申诉的目的是督促支付而非处罚。受理后通常一周内指派劳动监督官，约两周内安排出席调查。刑事告诉是另一条以处罚为目的的程序，请按目的选择。',
        vi: 'Khiếu nại nhằm được trả lương chứ không phải trừng phạt. Thường trong 1 tuần có thanh tra viên và khoảng 2 tuần có buổi điều tra. Tố cáo hình sự là thủ tục riêng nhằm xử phạt.',
        uz: "Shikoyat jazolashni emas, balki sizga pul toʻlanishini maqsad qiladi. Odatda bir hafta ichida inspektor tayinlanadi va yigʻilish taxminan ikki hafta ichida rejalashtiriladi. Jinoiy shikoyat jazolashni talab qiluvchi alohida yoʻldir — maqsadingizga qarab tanlang.",
      ),
    ),
    TrackStage(
      label: L10nText(
        ko: '출석 조사',
        en: 'Inspector meeting',
        tr: "Müfettiş toplantısı",
        tg: "Вохӯрии нозир",
        fil: "Pulong ng inspektor",
        ur: "انسپکٹر کی میٹنگ",
        th: "การประชุมกับเจ้าหน้าที่ตรวจสอบ",
        ky: "Инспектор менен жолугушуу",
        km: "ការប្រជុំអធិការ",
        id: "Pertemuan inspektur",
        si: "පරීක්ෂක රැස්වීම",
        bn: "পরিদর্শকের মিটিং",
        my: "စစ်ဆေးရေးမှူးနှင့် တွေ့ဆုံခြင်း",
        mn: "Мөрдөн байцаагчийн уулзалт",
        lo: "ການປະຊຸມກັບຜູ້ກວດກາ",
        tet: "Enkontru ho inspetór",
        ne: "निरीक्षक बैठक",
        zh: '出席调查',
        vi: 'Điều tra có mặt',
        uz: "Inspektor bilan uchrashuv",
      ),
      whatHappens: L10nText(
        ko: '담당 근로감독관의 호출에 따라 출석해 조사를 받는 단계입니다. 사업주와 주장이 엇갈리면 삼자대면이 잡힐 수 있습니다.',
        en: 'Attend the labor office when the inspector calls you in. If accounts differ, a three-way meeting may be arranged.',
        tr: "Müfettiş sizi çağırdığında çalışma ofisine gidin. Hesaplar farklılık gösterirse, üçlü bir toplantı düzenlenebilir.",
        tg: "Вақте ки нозир ба шумо занг мезанад, ба идораи меҳнат равед. Агар ҳисобҳо фарқ кунанд, вохӯрии сеҷониба ташкил карда мешавад.",
        fil:
            "Pumunta sa labor office kapag tinawag ka ng inspektor. Kung magkaiba ang mga account, maaaring magkaroon ng tripartite meeting.",
        ur: "جب انسپکٹر آپ کو بلائے تو لیبر آفس جائیں۔ اگر حسابات میں فرق ہو تو، ایک سہ فریقی میٹنگ کا اہتمام کیا جا سکتا ہے۔",
        th: "ไปที่สำนักงานแรงงานเมื่อเจ้าหน้าที่ตรวจสอบเรียกคุณ หากบัญชีมีความแตกต่างกัน อาจมีการจัดประชุมสามฝ่าย",
        ky: "Инспектор чакырганда эмгек кеңсесине барыңыз. Эгер эсептер дал келбесе, үч тараптуу жолугушуу уюштурулушу мүмкүн.",
        km: "ទៅការិយាល័យការងារនៅពេលដែលអធិការហៅអ្នក។ ប្រសិនបើគណនីខុសគ្នា ការប្រជុំត្រីភាគីអាចត្រូវបានរៀបចំឡើង។",
        id: "Pergi ke kantor tenaga kerja saat inspektur memanggil Anda. Jika ada perbedaan dalam perhitungan, pertemuan tiga pihak dapat diatur.",
        si: "පරීක්ෂකවරයා ඔබට කතා කරන විට කම්කරු කාර්යාලයට යන්න. ගිණුම් වෙනස් නම්, ත්‍රිත්ව රැස්වීමක් සංවිධානය කළ හැකිය.",
        bn: "পরিদর্শক আপনাকে ডাকলে শ্রম অফিসে যান। যদি হিসাবের পার্থক্য থাকে, তাহলে একটি ত্রিপক্ষীয় মিটিং আয়োজন করা যেতে পারে।",
        my: "စစ်ဆေးရေးမှူးက သင့်အား ခေါ်သောအခါ အလုပ်သမားရုံးသို့ သွားပါ။ အကောင့်များ ကွဲပြားပါက သုံးပွင့်ဆိုင်အစည်းအဝေးကို စီစဉ်နိုင်ပါသည်။",
        mn: "Мөрдөн байцаагч таныг дуудахад хөдөлмөрийн албанд очно уу. Хэрэв дансууд зөрүүтэй байвал гурван талт уулзалт зохион байгуулж болно.",
        lo: "ໄປທີ່ຫ້ອງການແຮງງານເມື່ອຜູ້ກວດກາໂທຫາທ່ານ. ຖ້າບັນຊີມີຄວາມແຕກຕ່າງກັນ, ອາດຈະມີການຈັດການປະຊຸມສາມຝ່າຍ.",
        tet:
            "Bainhira inspetór bolu imi, bá ba eskritóriu servisu. Se konta sira la hanesan, enkontru tripartidu ida bele organiza.",
        ne: "निरीक्षकले तपाईंलाई बोलाउँदा श्रम कार्यालयमा जानुहोस्। यदि हिसाबहरू फरक परेमा, त्रिपक्षीय बैठकको आयोजना गर्न सकिन्छ।",
        zh: '应劳动监督官传唤出席接受调查。若与雇主主张不一致，可能安排三方对质。',
        vi: 'Đến cơ quan lao động khi thanh tra viên triệu tập. Nếu lời khai khác nhau, có thể có buổi đối chất ba bên.',
        uz: "Inspektor sizni chaqirganda mehnat idorasiga boring. Agar hisoblar farq qilsa, uch tomonlama uchrashuv tashkil etilishi mumkin.",
      ),
      documentsNeeded: L10nText(
        ko: '신분증 / 제출 증거자료 원본 / 출석 통지서',
        en: 'ID / original evidence / summons letter',
        tr: "Kimlik / orijinal kanıt / tebligat mektubu",
        tg: "Шаҳодатномаи шахсият / далели аслӣ / мактуби даъват",
        fil: "ID / orihinal na ebidensya / sulat ng abiso",
        ur: "شناختی کارڈ / اصل ثبوت / نوٹس کا خط",
        th: "บัตรประจำตัว / หลักฐานต้นฉบับ / หนังสือแจ้ง",
        ky: "Өздүк күбөлүк / түп нуска далилдер / чакыруу каты",
        km: "អត្តសញ្ញាណប័ណ្ណ / ភស្តុតាងដើម / លិខិតជូនដំណឹង",
        id: "ID / bukti asli / surat panggilan",
        si: "හැඳුනුම්පත / මුල් සාක්ෂි / කැඳවීමේ ලිපිය",
        bn: "আইডি / মূল প্রমাণ / নোটিশের চিঠি",
        my: "သက်သေခံကတ်ပြား / မူရင်းအထောက်အထား / ဆင့်ခေါ်စာ",
        mn: "Иргэний үнэмлэх / эх баримт / дуудлагын бичиг",
        lo: "ບັດປະຈໍາຕົວ / ຫຼັກຖານຕົ້ນສະບັບ / ໜັງສືແຈ້ງການ",
        tet: "Identidade / prova orijinál / karta notifikasaun",
        ne: "परिचयपत्र / मौलिक प्रमाण / सूचना पत्र",
        zh: '身份证／提交证据原件／出席通知书',
        vi: 'Giấy tờ tùy thân / bản gốc chứng cứ / giấy triệu tập',
        uz: "ID / asl dalil / chaqiruv xati",
      ),
      watchOutFor: L10nText(
        ko: '사업주와 함께 있는 것이 불편하면 분리 조사를 요구할 수 있고, 통역원 동석도 미리 신청할 수 있습니다. 첫 조사에서 서류를 다 못 냈어도 이후 이메일·팩스·서면 의견서로 얼마든지 보완할 수 있으니 위축되지 마세요. 감독관이 합의를 권해도 받을 금액을 서둘러 깎을 이유는 없습니다.',
        en: 'You may ask to be questioned separately from your employer, and request an interpreter in advance. If you could not submit everything at the first meeting, you can supplement later by email, fax or written statement — do not be intimidated. Even if the inspector suggests settling, there is no reason to hastily cut what you are owed.',
        tr: "İşvereninizden ayrı sorgulanmayı talep edebilir ve önceden bir tercüman isteyebilirsiniz. İlk toplantıda her şeyi sunamadıysanız, daha sonra e-posta, faks veya yazılı beyanla tamamlayabilirsiniz — gözünüz korkmasın. Müfettiş uzlaşmayı önerse bile, size borçlu olunanı aceleyle kesmek için hiçbir neden yoktur.",
        tg: "Шумо метавонед талаб кунед, ки аз корфармои худ алоҳида пурсида шавед ва пешакӣ тарҷумонро дархост кунед. Агар шумо дар вохӯрии аввал ҳама чизро пешниҳод карда натавонистед, шумо метавонед онро баъдтар тавассути почтаи электронӣ, факс ё изҳороти хаттӣ пурра кунед — натарсед. Ҳатто агар нозир созишро пешниҳод кунад ҳам, ҳеҷ сабабе нест, ки шумо маблағи қарздори худро саросемавор кам кунед.",
        fil:
            "Maaari kang humiling na tanungin nang hiwalay mula sa iyong employer at humiling ng interpreter nang maaga. Kung hindi mo naibigay ang lahat sa unang pulong, maaari mo itong kumpletuhin sa ibang pagkakataon sa pamamagitan ng email, fax, o nakasulat na pahayag — huwag kang matakot. Kahit na imungkahi ng inspektor ang kompromiso, walang dahilan upang madaliang bawasan ang utang sa iyo.",
        ur: "آپ اپنے آجر سے الگ سے پوچھ گچھ کا مطالبہ کر سکتے ہیں اور پہلے سے ایک مترجم کی درخواست کر سکتے ہیں۔ اگر آپ پہلی میٹنگ میں سب کچھ پیش نہیں کر سکے، تو آپ بعد میں ای میل، فیکس، یا تحریری بیان کے ذریعے اسے مکمل کر سکتے ہیں — گھبرائیں نہیں۔ یہاں تک کہ اگر انسپکٹر سمجھوتہ کی تجویز پیش کرے، تو آپ کو واجب الادا رقم کو جلدی میں کم کرنے کی کوئی وجہ نہیں ہے۔",
        th: "คุณสามารถขอให้สอบปากคำแยกจากนายจ้างของคุณ และขอให้มีล่ามล่วงหน้าได้ หากคุณไม่สามารถนำเสนอทุกอย่างในการประชุมครั้งแรก คุณสามารถส่งเอกสารเพิ่มเติมทางอีเมล โทรสาร หรือคำให้การเป็นลายลักษณ์อักษรในภายหลังได้ — อย่ารู้สึกกดดัน แม้ว่าเจ้าหน้าที่ตรวจสอบจะแนะนำให้ประนีประนอม ก็ไม่มีเหตุผลใดที่คุณจะต้องรีบตัดเงินที่คุณควรได้รับ",
        ky: "Жумуш берүүчүңүздөн өзүнчө суракка алууну талап кылып, алдын ала котормочу сурасаңыз болот. Эгер биринчи жолугушууда бардыгын бере албасаңыз, кийинчерээк электрондук почта, факс же жазуу жүзүндөгү билдирүү аркылуу толуктасаңыз болот – коркпоңуз. Инспектор элдешүүнү сунуштаса дагы, сизге карыз болгон сумманы шашылыш кыскартууга эч кандай себеп жок.",
        km: "អ្នកអាចស្នើសុំឱ្យត្រូវបានសាកសួរដាច់ដោយឡែកពីនិយោជករបស់អ្នក ហើយស្នើសុំអ្នកបកប្រែជាមុន។ ប្រសិនបើអ្នកមិនអាចបង្ហាញអ្វីៗទាំងអស់នៅក្នុងកិច្ចប្រជុំដំបូងទេ អ្នកអាចបំពេញបន្ថែមនៅពេលក្រោយតាមរយៈអ៊ីមែល ទូរសារ ឬសេចក្តីថ្លែងការណ៍ជាលាយលក្ខណ៍អក្សរ — កុំភ័យខ្លាច។ ទោះបីជាអធិការណែនាំឱ្យសម្របសម្រួលក៏ដោយ ក៏គ្មានហេតុផលអ្វីដែលត្រូវកាត់បន្ថយអ្វីដែលអ្នកជំពាក់នោះទេ។",
        id: "Anda dapat meminta untuk diinterogasi secara terpisah dari atasan Anda dan meminta penerjemah sebelumnya. Jika Anda tidak dapat menyerahkan semuanya pada pertemuan pertama, Anda dapat melengkapinya nanti melalui email, faks, atau pernyataan tertulis — jangan terintimidasi. Bahkan jika inspektur menyarankan kompromi, tidak ada alasan untuk terburu-buru memotong apa pun yang menjadi hak Anda.",
        si: "ඔබේ සේවායෝජකයාගෙන් වෙන්ව ප්‍රශ්න කිරීමට ඉල්ලා සිටිය හැකි අතර කල්තියා පරිවර්තකයෙකු ඉල්ලා සිටිය හැකිය. ඔබට පළමු රැස්වීමේදී සියල්ල ඉදිරිපත් කිරීමට නොහැකි වූයේ නම්, ඔබට පසුව විද්‍යුත් තැපෑල, ෆැක්ස් හෝ ලිඛිත ප්‍රකාශයක් මගින් එය සම්පූර්ණ කළ හැකිය - බිය නොවන්න. පරීක්ෂකවරයා සමථයකට පත්වීමට යෝජනා කළත්, ඔබට හිමි දේ කඩිමුඩියේ කපා හැරීමට හේතුවක් නැත.",
        bn: "আপনি আপনার নিয়োগকর্তা থেকে আলাদাভাবে জিজ্ঞাসাবাদ করার অনুরোধ করতে পারেন এবং আগে থেকে একজন দোভাষী চাইতে পারেন। যদি আপনি প্রথম মিটিংয়ে সবকিছু জমা দিতে না পারেন, তাহলে আপনি পরে ইমেল, ফ্যাক্স বা লিখিত বিবৃতি দিয়ে তা সম্পূর্ণ করতে পারেন — ভয় পাবেন না। পরিদর্শক আপস করার প্রস্তাব দিলেও, আপনাকে যা পাওনা তা তাড়াহুড়ো করে কেটে ফেলার কোনো কারণ নেই।",
        my: "သင်၏အလုပ်ရှင်နှင့် သီးခြားစစ်ဆေးမေးမြန်းရန် တောင်းဆိုနိုင်ပြီး ဘာသာပြန်တစ်ဦးကို ကြိုတင်တောင်းဆိုနိုင်ပါသည်။ ပထမအစည်းအဝေးတွင် အရာအားလုံးကို မတင်ပြနိုင်ခဲ့ပါက နောက်ပိုင်းတွင် အီးမေးလ်၊ ဖက်စ် သို့မဟုတ် စာဖြင့်ရေးသားထားသော ထွက်ဆိုချက်ဖြင့် ဖြည့်စွက်နိုင်သည် — မကြောက်ပါနှင့်။ စစ်ဆေးရေးမှူးက ညှိနှိုင်းရန် အကြံပြုသော်လည်း သင့်အား ပေးဆပ်ရမည့်အရာကို အလျင်စလို လျှော့ချရန် အကြောင်းပြချက်မရှိပါ။",
        mn: "Та ажил олгогчоосоо тусад нь байцаалт авахыг хүсч, орчуулагчийг урьдчилан хүсч болно. Хэрэв та эхний уулзалтад бүх зүйлийг өгч чадаагүй бол дараа нь имэйл, факс эсвэл бичгээр гаргасан мэдэгдлээр нөхөж болно - айх хэрэггүй. Мөрдөн байцаагч эвлэрэхийг санал болгосон ч танд өртэй байгаа зүйлийг яаран хасах шалтгаан байхгүй.",
