        th: "คุณสามารถยื่นคำขอได้โดยใช้เพียงหนังสือจากสำนักงานแรงงานโดยไม่ต้องมีคำสั่งศาล และมีรายงานว่าการชำระเงินจะใช้เวลาประมาณสองเดือน มีระยะเวลาในการยื่นคำขอ ดังนั้นโปรดดำเนินการทันทีที่คุณได้รับจดหมาย",
        ky: "Соттун чечимисиз эле эмгек кеңсесинин каты менен талап кыла аласыз, жана төлөм болжол менен эки айга созулат деп билдирилген. Арыз берүү мөөнөтү бар, андыктан катты алгандан кийин дароо аракет кылыңыз.",
        km: "អ្នកអាចដាក់ពាក្យស្នើសុំដោយគ្រាន់តែលិខិតពីការិយាល័យការងារដោយគ្មានដីកាតុលាការ ហើយការទូទាត់ត្រូវបានរាយការណ៍ថាចំណាយពេលប្រហែលពីរខែ។ មានរយៈពេលដាក់ពាក្យស្នើសុំ ដូច្នេះសូមបន្តភ្លាមៗនៅពេលអ្នកទទួលបានលិខិតនោះ។",
        id: "Anda dapat mengajukan klaim hanya dengan surat kantor tenaga kerja tanpa putusan pengadilan, dan pembayaran dilaporkan memakan waktu sekitar dua bulan. Ada batas waktu pengajuan, jadi segera setelah Anda menerima surat tersebut, lanjutkan.",
        si: "ඔබට අධිකරණ නියෝගයක් නොමැතිව කම්කරු කාර්යාල ලිපිය සමඟ පමණක් ඉල්ලීමක් කළ හැකි අතර ගෙවීම සඳහා මාස දෙකක් පමණ ගත වන බව වාර්තා වේ. අයදුම් කිරීමේ කාල සීමාවක් ඇත, එබැවින් ලිපිය ලැබුණු වහාම ඉදිරියට යන්න.",
        bn: "আপনি আদালতের আদেশ ছাড়াই শুধুমাত্র শ্রম অফিসের চিঠি দিয়ে দাবি করতে পারেন এবং অর্থপ্রদান পেতে প্রায় দুই মাস সময় লাগে বলে জানা গেছে। একটি আবেদন সময়সীমা আছে, তাই চিঠিটি পাওয়ার সাথে সাথে এগিয়ে যান।",
        my: "တရားရုံးအမိန့်မပါဘဲ အလုပ်သမားရုံးစာဖြင့်သာ တောင်းဆိုနိုင်ပြီး ငွေပေးချေမှုသည် နှစ်လခန့် ကြာသည်ဟု ဖော်ပြထားပါသည်။ လျှောက်လွှာတင်ရမည့် ကာလတစ်ခုရှိသောကြောင့် စာရသည်နှင့် ချက်ချင်းဆောင်ရွက်ပါ။",
        mn: "Та шүүхийн шийдвэргүйгээр зөвхөн хөдөлмөрийн албаны бичгээр нэхэмжлэл гаргаж болох бөгөөд төлбөр хийхэд хоёр сар орчим хугацаа шаардагдана гэж мэдээлэгдсэн. Өргөдөл гаргах хугацаа байдаг тул бичгийг хүлээн авмагц үргэлжлүүлээрэй.",
        lo: "ທ່ານສາມາດຮ້ອງຂໍໄດ້ພຽງແຕ່ດ້ວຍໜັງສືຈາກຫ້ອງການແຮງງານໂດຍບໍ່ມີຄໍາສັ່ງສານ, ແລະ ມີລາຍງານວ່າການຈ່າຍເງິນໃຊ້ເວລາປະມານສອງເດືອນ. ມີໄລຍະເວລາການສະໝັກ, ດັ່ງນັ້ນໃຫ້ດໍາເນີນການທັນທີທີ່ທ່ານໄດ້ຮັບໜັງສື.",
        tet:
            "Imi bele halo pedidu ho karta eskritóriu servisu de'it, la presiza desizaun tribunál no pagamentu sei demora maizumenus fulan rua. Iha prazu ba aplikasaun, tanba ne'e, bainhira simu karta, kontinua kedas.",
        ne: "तपाईं अदालतको आदेश बिना श्रम कार्यालयको पत्रको साथ मात्र दाबी गर्न सक्नुहुन्छ र भुक्तानी हुन लगभग दुई महिना लाग्ने बताइएको छ। आवेदनको लागि समय सीमा हुन्छ, त्यसैले पत्र प्राप्त गर्ने बित्तिकै अगाडि बढ्नुहोस्।",
        zh: '无需法院判决，仅凭劳动厅确认书即可请求，据载约两个月内支付。有申请期限，拿到确认书后请勿拖延。',
        vi: 'Có thể yêu cầu chỉ với giấy của cơ quan lao động, không cần phán quyết tòa, và thường được chi trả trong khoảng hai tháng. Có thời hạn nộp, nên hãy làm ngay khi nhận giấy.',
        uz: "Siz sud qarorisiz, faqat mehnat idorasi xati bilan daʼvo qilishingiz mumkin va toʻlov taxminan ikki oy davom etishi xabar qilingan. Ariza berish muddati bor, shuning uchun xatni olganingizdan soʻng darhol harakat qiling.",
      ),
