        lo: "ເມື່ອຈໍານວນເງິນເກີນຂີດຈໍາກັດເງິນລ່ວງໜ້າ ຫຼື ນາຍຈ້າງຍັງຄົງປະຕິເສດ, ໃຫ້ຂໍຄໍາສັ່ງສານ. ຄໍາສັ່ງຈ່າຍເງິນຈະດໍາເນີນການໂດຍອີງໃສ່ເອກະສານເທົ່ານັ້ນໂດຍບໍ່ມີການໄຕ່ສວນ.",
