        ne: "जब रकम अग्रिम सीमा भन्दा बढी हुन्छ वा रोजगारदाताले अस्वीकार गरिरहन्छ, अदालतको आदेश प्राप्त गर्नुहोस्। भुक्तानी आदेश सुनुवाइ बिना कागजातहरूको आधारमा मात्र अगाडि बढ्छ।",
        zh: '欠薪额超过代付金上限或雇主继续拖延时，取得执行依据。支付令仅凭书面进行，无需出庭。',
