        my: "အတည်ပြုစာ / တရားရေးဆိုင်ရာ တိုင်ကြားစာ သို့မဟုတ် ငွေပေးချေမှုအမိန့် လျှောက်လွှာ",
        mn: "Баталгаажуулах бичиг / хуулийн гомдол эсвэл төлбөрийн захирамжийн өргөдөл",
        lo: "ໜັງສືຢັ້ງຢືນ / ຄໍາຮ້ອງທຸກທາງກົດໝາຍ ຫຼື ຄໍາຮ້ອງຂໍຄໍາສັ່ງຈ່າຍເງິນ",
        tet: "Karta konfirmasaun / keixa legál ka aplikasaun orden pagamentu",
        ne: "अनुमोदन पत्र / कानुनी उजुरी वा भुक्तानी आदेशको आवेदन",
        zh: '确认书／民事诉状或支付令申请书',
        vi: 'Giấy xác nhận / đơn kiện hoặc đơn xin lệnh thanh toán',
        uz: "Tasdiqlash xati / fuqarolik shikoyati yoki toʻlov buyrugʻi arizasi",
      ),
      watchOutFor: L10nText(
        ko: '월 평균임금이 일정 기준 미만이면 대한법률구조공단(대표번호 132)의 무료 법률구조를 받을 수 있습니다. 소득 요건을 먼저 확인하세요. 체불액이 3,000만원 이하면 소액사건심판으로 더 간단히 갈 수 있습니다.',
        en: 'If your average monthly wage is below a set threshold, the Korea Legal Aid Corporation (132) provides free assistance — check the income requirement first. Claims of 30 million won or less can go through the simplified small-claims procedure.',
        tr: "Ortalama aylık ücretiniz belirlenen bir eşiğin altındaysa, Kore Hukuki Yardım Kurumu (132) ücretsiz yardım sağlar — önce gelir şartını kontrol edin. 30 milyon won veya daha az tutardaki talepler basitleştirilmiş küçük alacaklar prosedürüyle ilerleyebilir.",
        tg: "Агар музди миёнаи моҳонаи шумо аз ҳадди муайяншуда камтар бошад, Агентии кӯмаки ҳуқуқии Корея (132) кӯмаки ройгон мерасонад — аввал шарти даромадро тафтиш кунед. Даъвоҳое, ки маблағашон 30 миллион вон ё камтар аст, метавонанд тавассути тартиби соддакардашудаи даъвоҳои хурд пеш раванд.",
        fil:
            "Kung ang iyong average na buwanang sahod ay mas mababa sa isang itinakdang threshold, ang Korea Legal Aid Corporation (132) ay nagbibigay ng libreng tulong — suriin muna ang kinakailangan sa kita. Ang mga claim na 30 milyong won o mas mababa ay maaaring magpatuloy sa pamamagong ng pinasimpleng pamamaraan para sa maliliit na claim.",
        ur: "اگر آپ کی اوسط ماہانہ اجرت ایک مقررہ حد سے کم ہے، تو کوریا لیگل ایڈ کارپوریشن (132) مفت مدد فراہم کرتی ہے — پہلے آمدنی کی شرط چیک کریں۔ 30 ملین وون یا اس سے کم کے دعوے آسان چھوٹے دعووں کے طریقہ کار کے ذریعے آگے بڑھ سکتے ہیں۔",
        th: "หากค่าจ้างเฉลี่ยต่อเดือนของคุณต่ำกว่าเกณฑ์ที่กำหนด สถาบันช่วยเหลือทางกฎหมายของเกาหลี (132) จะให้ความช่วยเหลือฟรี — โปรดตรวจสอบเงื่อนไขรายได้ก่อน คำขอที่มีมูลค่า 30 ล้านวอนหรือน้อยกว่าสามารถดำเนินการได้ด้วยขั้นตอนการเรียกร้องค่าเสียหายเล็กน้อยที่เรียบง่าย",
        ky: "Эгер орточо айлык эмгек акыңыз белгиленген чектен төмөн болсо, Кореянын Юридикалык Жардам Корпорациясы (132) акысыз жардам көрсөтөт – алгач киреше талабын текшериңиз. 30 миллион вон же андан аз суммадагы талаптар жөнөкөйлөтүлгөн чакан дооматтар процедурасы аркылуу жүргүзүлүшү мүмкүн.",
        km: "ប្រសិនបើប្រាក់ឈ្នួលប្រចាំខែជាមធ្យមរបស់អ្នកស្ថិតនៅក្រោមដែនកំណត់ដែលបានកំណត់ ស្ថាប័នជំនួយផ្លូវច្បាប់កូរ៉េ (132) ផ្តល់ជំនួយដោយឥតគិតថ្លៃ — សូមពិនិត្យមើលលក្ខខណ្ឌប្រាក់ចំណូលជាមុនសិន។ ការទាមទារដែលមានចំនួន 30 លានវ៉ុន ឬតិចជាងនេះអាចដំណើរការតាមរយៈនីតិវិធីបំណុលតូចតាចដែលបានសម្រួល។",
        id: "Jika gaji bulanan rata-rata Anda di bawah ambang batas yang ditentukan, Korea Legal Aid Corporation (132) memberikan bantuan gratis — periksa persyaratan pendapatan terlebih dahulu. Klaim sebesar 30 juta won atau kurang dapat dilanjutkan melalui prosedur klaim kecil yang disederhanakan.",
        si: "ඔබේ සාමාන්‍ය මාසික වැටුප නියමිත සීමාවකට වඩා අඩු නම්, කොරියානු නීති ආධාර සංස්ථාව (132) නොමිලේ ආධාර සපයයි - පළමුව ආදායම් අවශ්‍යතාවය පරීක්ෂා කරන්න. වොන් මිලියන 30 ක් හෝ ඊට අඩු හිමිකම් සරල කළ කුඩා හිමිකම් ක්‍රියා පටිපාටිය හරහා ඉදිරියට යා හැකිය.",
        bn: "যদি আপনার গড় মাসিক মজুরি একটি নির্দিষ্ট সীমার নিচে হয়, তাহলে কোরিয়া লিগ্যাল এইড কর্পোরেশন (132) বিনামূল্যে সহায়তা প্রদান করে — প্রথমে আয়ের যোগ্যতা পরীক্ষা করুন। 30 মিলিয়ন ওন বা তার কম পরিমাণের দাবিগুলি সরলীকৃত ছোট দাবি প্রক্রিয়া দ্বারা এগিয়ে যেতে পারে।",
        my: "သင်၏ပျမ်းမျှလစဉ်လုပ်ခသည် သတ်မှတ်ထားသော ကန့်သတ်ချက်အောက်တွင် ရှိပါက ကိုရီးယားတရားရေးအကူအညီအဖွဲ့ (132) က အခမဲ့အကူအညီပေးသည် — ဝင်ငွေလိုအပ်ချက်ကို ဦးစွာစစ်ဆေးပါ။ ဝမ် 30 သန်း သို့မဟုတ် ထို့ထက်နည်းသော တောင်းဆိုမှုများကို ရိုးရှင်းသော အသေးစားတောင်းဆိုမှုလုပ်ထုံးလုပ်နည်းဖြင့် ဆောင်ရွက်နိုင်ပါသည်။",
        mn: "Хэрэв таны дундаж сарын цалин тогтоосон босгоос доогуур байвал Солонгосын Хууль зүйн туслалцааны корпораци (132) үнэ төлбөргүй тусламж үзүүлдэг - эхлээд орлогын шаардлагыг шалгана уу. 30 сая вон ба түүнээс бага дүнтэй нэхэмжлэлийг хялбаршуулсан жижиг нэхэмжлэлийн журмаар шийдвэрлэж болно.",
        lo: "ຖ້າຄ່າຈ້າງສະເລ່ຍຕໍ່ເດືອນຂອງທ່ານຕໍ່າກວ່າເກນທີ່ກໍານົດໄວ້, ອົງການຊ່ວຍເຫຼືອທາງກົດໝາຍເກົາຫຼີ (132) ໃຫ້ການຊ່ວຍເຫຼືອຟຣີ — ກວດເບິ່ງເງື່ອນໄຂລາຍໄດ້ກ່ອນ. ການຮ້ອງຂໍທີ່ມີມູນຄ່າ 30 ລ້ານວອນ ຫຼື ໜ້ອຍກວ່ານັ້ນສາມາດດໍາເນີນການຜ່ານຂັ້ນຕອນການຮ້ອງຂໍຂະໜາດນ້ອຍແບບງ່າຍດາຍ.",
        tet:
            "Se imi-nia saláriu médiu fulan-fulan nian menus husi limite ne'ebé estabelese, Korea Legal Aid Corporation (132) sei fó asisténsia gratuita — verifika uluk kondisaun rendimentu. Pedidu sira ho montante 30 millaun won ka menus bele kontinua ho prosedimentu simplifikadu ba dívida ki'ik.",
        ne: "यदि तपाईंको औसत मासिक ज्याला तोकिएको सीमा भन्दा कम छ भने, कोरिया कानूनी सहायता निगम (132) ले निःशुल्क सहायता प्रदान गर्दछ — पहिले आयको शर्त जाँच गर्नुहोस्। 30 मिलियन KRW वा सोभन्दा कम रकमका दाबीहरू सरलीकृत साना दाबी प्रक्रिया मार्फत अगाडि बढ्न सक्छन्।",
        zh: '若月平均工资低于一定标准，可获大韩法律救助公团（代表号132）免费法律救助，请先确认收入条件。欠薪额在3,000万韩元以下可走更简便的小额审判程序。',
        vi: 'Nếu lương bình quân tháng dưới ngưỡng quy định, Trung tâm Trợ giúp pháp lý Hàn Quốc (132) hỗ trợ miễn phí — hãy kiểm tra điều kiện thu nhập. Số tiền từ 30 triệu won trở xuống có thể theo thủ tục án nhỏ đơn giản hơn.',
        uz: "Agar sizning oʻrtacha oylik ish haqingiz belgilangan chegaradan past boʻlsa, Koreya Yuridik Yordam Korporatsiyasi (132) bepul yordam koʻrsatadi — avval daromad talabini tekshiring. 30 million von yoki undan kam boʻlgan daʼvolar soddalashtirilgan kichik daʼvolar tartibi orqali koʻrib chiqilishi mumkin.",
      ),
    ),
