        ur: "آجر کے اثاثوں کے خلاف اجرا نافذ کریں اور بقایا اجرت کی وجہ سے کام کی جگہ کی تبدیلی کو حل کریں۔",
        th: "ดำเนินการบังคับคดีกับทรัพย์สินของนายจ้าง และจัดการกับการเปลี่ยนแปลงสถานที่ทำงานที่เกิดจากค่าจ้างที่ค้างชำระ",
        ky: "Жумуш берүүчүнүн мүлкүнө карата аткарууну колдонуңуз жана төлөнбөгөн эмгек акыдан улам келип чыккан жумуш ордун алмаштыруу маселесин чечиңиз.",
        km: "អនុវត្តការអនុវត្តប្រឆាំងនឹងទ្រព្យសម្បត្តិរបស់និយោជក និងដោះស្រាយការផ្លាស់ប្តូរកន្លែងធ្វើការដែលបណ្តាលមកពីប្រាក់ឈ្នួលដែលមិនទាន់បានបង់។",
        id: "Terapkan eksekusi terhadap aset atasan dan tangani perubahan tempat kerja yang disebabkan oleh upah yang belum dibayar.",
        si: "සේවායෝජකයාගේ වත්කම්වලට එරෙහිව බලාත්මක කිරීම ක්‍රියාත්මක කර නොගෙවූ වැටුප් නිසා ඇති වූ සේවා ස්ථාන වෙනස් කිරීම විසඳන්න.",
        bn: "নিয়োগকর্তার সম্পদের বিরুদ্ধে বাস্তবায়ন প্রয়োগ করুন এবং বকেয়া মজুরির কারণে কর্মস্থল পরিবর্তন মোকাবেলা করুন।",
        my: "အလုပ်ရှင်၏ ပိုင်ဆိုင်မှုများကို အကောင်အထည်ဖော်ပြီး မပေးရသေးသောလုပ်ခလစာများကြောင့် အလုပ်နေရာပြောင်းလဲခြင်းကို ကိုင်တွယ်ပါ။",
        mn: "Ажил олгогчийн хөрөнгөнд гүйцэтгэх ажиллагаа явуулж, төлөгдөөгүй цалингаас үүдэлтэй ажлын байрны өөрчлөлтийг шийдвэрлэнэ.",
        lo: "ບັງຄັບໃຊ້ຕໍ່ຊັບສິນຂອງນາຍຈ້າງ ແລະ ຈັດການກັບການປ່ຽນແປງສະຖານທີ່ເຮັດວຽກທີ່ເກີດຈາກຄ່າຈ້າງທີ່ຄ້າງຈ່າຍ.",
        tet:
            "Halo ezekusaun hasoru empregadór nia sasán no rezolve kestaun troka fatin servisu ne'ebé kauza husi saláriu ne'ebé seidauk selu.",
        ne: "रोजगारदाताको सम्पत्ति विरुद्ध कार्यान्वयन लागू गर्नुहोस् र नतिरेको ज्यालाका कारण हुने कार्यस्थल परिवर्तनलाई सम्बोधन गर्नुहोस्।",
        zh: '对雇主财产进行扣押·拍卖，并办理因欠薪的单位变更。',
        vi: 'Thi hành đối với tài sản của chủ và xử lý việc chuyển nơi làm do bị nợ lương.',
        uz: "Ish beruvchining aktivlariga nisbatan ijro eting va toʻlanmagan ish haqi tufayli ish joyi oʻzgarishini hal qiling.",
      ),
      documentsNeeded: L10nText(
        ko: '확정 판결문·지급명령 결정문 / 사업장 변경 신청서',
        en: 'Final judgement or payment order / workplace change application',
        tr: "Nihai karar veya ödeme emri / işyeri değişikliği başvurusu",
        tg: "Қарори ниҳоӣ ё фармони пардохт / ариза барои тағйири ҷои кор",
        fil:
            "Pinal na desisyon o payment order / aplikasyon para sa pagbabago ng lugar ng trabaho",
        ur: "حتمی فیصلہ یا ادائیگی کا حکم / کام کی جگہ کی تبدیلی کی درخواست",
        th: "คำตัดสินสุดท้ายหรือคำสั่งให้ชำระเงิน / การยื่นขอเปลี่ยนแปลงสถานที่ทำงาน",
        ky: "Акыркы чечим же төлөм буйругу / жумуш ордун алмаштырууга арыз",
        km: "សេចក្តីសម្រេចចុងក្រោយ ឬដីកាបញ្ជាទូទាត់ប្រាក់ / ពាក្យស្នើសុំផ្លាស់ប្តូរកន្លែងធ្វើការ",
        id: "Putusan akhir atau perintah pembayaran / permohonan perubahan tempat kerja",
        si: "අවසාන තීන්දුව හෝ ගෙවීම් නියෝගය / සේවා ස්ථාන වෙනස් කිරීමේ අයදුම්පත",
        bn: "চূড়ান্ত রায় বা অর্থপ্রদানের আদেশ / কর্মস্থল পরিবর্তনের আবেদন",
        my: "နောက်ဆုံးဆုံးဖြတ်ချက် သို့မဟုတ် ငွေပေးချေမှုအမိန့် / အလုပ်နေရာပြောင်းလဲခြင်းလျှောက်လွှာ",
        mn: "Эцсийн шийдвэр эсвэл төлбөрийн захирамж / ажлын байрны өөрчлөлтийн өргөдөл",
        lo: "ຄໍາຕັດສິນສຸດທ້າຍ ຫຼື ຄໍາສັ່ງຈ່າຍເງິນ / ຄໍາຮ້ອງຂໍປ່ຽນສະຖານທີ່ເຮັດວຽກ",
        tet:
            "Desizaun finál ka orden pagamentu / aplikasaun troka fatin servisu",
        ne: "अन्तिम निर्णय वा भुक्तानी आदेश / कार्यस्थल परिवर्तनको आवेदन",
        zh: '确定判决书·支付令决定书／单位变更申请书',
        vi: 'Bản án/lệnh thanh toán / đơn xin chuyển nơi làm việc',
        uz: "Yakuniy qaror yoki toʻlov buyrugʻi / ish joyi oʻzgarishi arizasi",
      ),
      watchOutFor: L10nText(
        ko: '판결을 받아도 사업주에게 압류할 재산이 없으면 실제 회수가 어렵습니다. 노동청 단계부터 사업자 계좌·차량·거래처 같은 재산 상태를 함께 살펴두고, 재산을 빼돌리는 정황이 보이면 가압류를 먼저 걸어두는 편이 낫습니다. 체불이 증명되면 사업장 변경 횟수에서 차감되지 않습니다.',
        en: 'Even with a judgement, recovery is hard if there are no assets to seize. From the labor office stage, check for business accounts, vehicles and clients, and consider provisional attachment if assets are being moved. If the unpaid wages are proven, this change does not count against your workplace-change quota.',
        tr: "Bir karar olsa bile, haczedilecek varlık yoksa tahsilat zordur. Çalışma ofisi aşamasından itibaren, ticari hesapları, araçları ve müşterileri kontrol edin ve varlıklar taşınıyorsa ihtiyati haciz düşünün. Ödenmemiş ücretler kanıtlanırsa, bu değişiklik işyeri değiştirme kotanıza sayılmaz.",
        tg: "Ҳатто агар қарор мавҷуд бошад ҳам, агар дороиҳо барои мусодира вуҷуд надошта бошанд, ҷамъоварӣ душвор аст. Аз марҳилаи идораи меҳнат, суратҳисобҳои тиҷоратӣ, воситаҳои нақлиёт ва муштариёнро тафтиш кунед ва агар дороиҳо интиқол дода шаванд, мусодираи эҳтиётиро баррасӣ кунед. Агар музди меҳнати пардохтнашуда исбот шавад, ин тағйирот ба квотаи тағйири ҷои кори шумо ҳисоб карда намешавад.",
        fil:
            "Kahit may desisyon, mahirap ang koleksyon kung walang ari-arian na kukunin. Mula sa yugto ng labor office, suriin ang mga account ng negosyo, sasakyan, at mga customer, at isaalang-alang ang precautionary attachment kung inililipat ang mga ari-arian. Kung mapatunayan ang hindi nabayarang sahod, ang pagbabagong ito ay hindi mabibilang sa iyong quota sa pagbabago ng lugar ng trabaho.",
        ur: "فیصلہ ہونے کے باوجود، اگر ضبط کرنے کے لیے کوئی اثاثے نہیں ہیں تو وصولی مشکل ہے۔ لیبر آفس کے مرحلے سے ہی، کاروباری کھاتوں، گاڑیوں اور گاہکوں کی جانچ کریں، اور اگر اثاثے منتقل ہو رہے ہوں تو احتیاطی ضبطی پر غور کریں۔ اگر بقایا اجرت ثابت ہو جاتی ہے، تو یہ تبدیلی آپ کے کام کی جگہ کی تبدیلی کے کوٹے میں شمار نہیں ہوگی۔",
        th: "แม้จะมีคำตัดสินแล้ว การเรียกเก็บเงินก็ยังเป็นเรื่องยากหากไม่มีทรัพย์สินให้ยึด ตั้งแต่ขั้นตอนของสำนักงานแรงงาน ให้ตรวจสอบบัญชีธุรกิจ ยานพาหนะ และลูกค้า และพิจารณาการยึดทรัพย์สินเพื่อป้องกันหากมีการย้ายทรัพย์สิน หากพิสูจน์ได้ว่ามีค่าจ้างที่ค้างชำระ การเปลี่ยนแปลงนี้จะไม่นับรวมในโควตาการเปลี่ยนสถานที่ทำงานของคุณ",
        ky: "Чечим болсо дагы, эгерде камакка алына турган мүлк жок болсо, чогултуу кыйынга турат. Эмгек кеңсесинин баскычынан баштап, коммерциялык эсептерди, унааларды жана кардарларды текшериңиз, эгерде мүлк которулуп жатса, алдын ала камакка алууну карап көрүңүз. Эгерде төлөнбөгөн эмгек акы далилденсе, бул өзгөртүү сиздин жумуш ордун алмаштыруу квотаңызга кирбейт.",
        km: "ទោះបីជាមានសេចក្តីសម្រេចក៏ដោយ ការប្រមូលប្រាក់គឺពិបាកប្រសិនបើគ្មានទ្រព្យសម្បត្តិសម្រាប់រឹបអូស។ ចាប់ពីដំណាក់កាលការិយាល័យការងារ សូមពិនិត្យមើលគណនីអាជីវកម្ម យានយន្ត និងអតិថិជន ហើយពិចារណាការរឹបអូសជាបណ្តោះអាសន្ន ប្រសិនបើទ្រព្យសម្បត្តិកំពុងត្រូវបានផ្លាស់ប្តូរ។ ប្រសិនបើប្រាក់ឈ្នួលដែលមិនទាន់បានបង់ត្រូវបានបញ្ជាក់ ការផ្លាស់ប្តូរនេះនឹងមិនត្រូវបានរាប់បញ្ចូលក្នុងកូតាផ្លាស់ប្តូរកន្លែងធ្វើការរបស់អ្នកទេ។",
        id: "Bahkan dengan putusan, penagihan sulit jika tidak ada aset yang dapat disita. Sejak tahap kantor tenaga kerja, periksa rekening bisnis, kendaraan, dan pelanggan, dan pertimbangkan penyitaan sementara jika aset dipindahkan. Jika upah yang belum dibayar terbukti, perubahan ini tidak akan dihitung terhadap kuota perubahan tempat kerja Anda.",
        si: "තීන්දුවක් තිබුණත්, අත්අඩංගුවට ගැනීමට වත්කම් නොමැති නම් එකතු කිරීම අපහසුය. කම්කරු කාර්යාල අදියරේ සිට, ව්‍යාපාරික ගිණුම්, වාහන සහ ගනුදෙනුකරුවන් පරීක්ෂා කර වත්කම් ගෙන යන්නේ නම් පූර්වගාමී අත්අඩංගුවට ගැනීමක් සලකා බලන්න. නොගෙවූ වැටුප් ඔප්පු වුවහොත්, මෙම වෙනස ඔබේ සේවා ස්ථාන වෙනස් කිරීමේ කෝටාවට ගණන් නොගනී.",
        bn: "একটি রায় থাকলেও, যদি বাজেয়াপ্ত করার মতো কোনো সম্পদ না থাকে তবে সংগ্রহ করা কঠিন। শ্রম অফিসের পর্যায় থেকে, ব্যবসার অ্যাকাউন্ট, যানবাহন এবং গ্রাহকদের পরীক্ষা করুন এবং যদি সম্পদ সরানো হয় তবে সতর্কতামূলক সংযুক্তি বিবেচনা করুন। যদি বকেয়া মজুরি প্রমাণিত হয়, তাহলে এই পরিবর্তন আপনার কর্মস্থল পরিবর্তনের কোটায় গণনা করা হবে না।",
        my: "ဆုံးဖြတ်ချက်ရှိသော်လည်း သိမ်းဆည်းရန် ပိုင်ဆိုင်မှုမရှိပါက ငွေစုဆောင်းရန် ခက်ခဲပါသည်။ အလုပ်သမားရုံးအဆင့်မှစ၍ လုပ်ငန်းအကောင့်များ၊ ယာဉ်များနှင့် ဖောက်သည်များကို စစ်ဆေးပြီး ပိုင်ဆိုင်မှုများ ရွှေ့ပြောင်းနေပါက ကြိုတင်သိမ်းဆည်းခြင်းကို စဉ်းစားပါ။ မပေးရသေးသောလုပ်ခလစာများ မှန်ကန်ကြောင်း သက်သေပြနိုင်ပါက ဤပြောင်းလဲမှုသည် သင်၏အလုပ်နေရာပြောင်းလဲခြင်း ကန့်သတ်ချက်တွင် ထည့်သွင်းမည်မဟုတ်ပါ။",
        mn: "Шийдвэр гарсан ч хураах хөрөнгө байхгүй бол цуглуулах нь хэцүү байдаг. Хөдөлмөрийн албаны үе шатаас эхлэн бизнесийн данс, тээврийн хэрэгсэл, үйлчлүүлэгчдийг шалгаж, хөрөнгийг шилжүүлж байгаа бол урьдчилан сэргийлэх зорилгоор хураах талаар бодож үзээрэй. Хэрэв төлөгдөөгүй цалин батлагдвал энэ өөрчлөлт нь таны ажлын байрны өөрчлөлтийн квотод тооцогдохгүй.",
        lo: "ເຖິງແມ່ນວ່າມີຄໍາຕັດສິນ, ການເກັບກໍາຍາກຖ້າບໍ່ມີຊັບສິນທີ່ຈະຍຶດ. ຕັ້ງແຕ່ຂັ້ນຕອນຂອງຫ້ອງການແຮງງານ, ໃຫ້ກວດສອບບັນຊີທຸລະກິດ, ພາຫະນະ, ແລະ ລູກຄ້າ, ແລະ ພິຈາລະນາການຍຶດຊັບສິນຊົ່ວຄາວຖ້າຊັບສິນຖືກຍ້າຍ. ຖ້າຄ່າຈ້າງທີ່ຄ້າງຈ່າຍຖືກພິສູດ, ການປ່ຽນແປງນີ້ຈະບໍ່ຖືກນັບເຂົ້າໃນໂຄຕາການປ່ຽນສະຖານທີ່ເຮັດວຽກຂອງທ່ານ.",
        tet:
            "Maski iha desizaun ida, se la iha sasán atu halo penhora, kobransa sei susar. Husi faze eskritóriu servisu nian, verifika konta komersiál, veíkulu no kliente sira no konsidera penhora prekauzional se sasán sira muda hela. Se saláriu ne'ebé seidauk selu prova ona, mudansa ne'e la konta ba imi-nia kuota troka fatin servisu.",
        ne: "निर्णय भए पनि, यदि जफत गर्न कुनै सम्पत्ति छैन भने, सङ्कलन गर्न गाह्रो हुन्छ। श्रम कार्यालयको चरणदेखि नै, व्यापारिक खाताहरू, सवारी साधनहरू र ग्राहकहरू जाँच गर्नुहोस् र यदि सम्पत्तिहरू सारिँदै छन् भने, अस्थायी जफत विचार गर्नुहोस्। यदि नतिरेको ज्याला प्रमाणित हुन्छ भने, यो परिवर्तन तपाईंको कार्यस्थल परिवर्तन कोटामा गणना गरिने छैन।",
        zh: '即使取得判决，若雇主无可扣押财产也难以实际回收。从劳动厅阶段起就一并了解其账户·车辆·交易方等财产状况，若发现转移财产迹象宜先申请假扣押。欠薪一经证明，此次变更不计入单位变更次数。',
        vi: 'Dù có phán quyết, khó thu hồi nếu chủ không còn tài sản. Ngay từ giai đoạn cơ quan lao động, hãy nắm tài khoản, xe, đối tác của chủ; nếu thấy tẩu tán tài sản, nên xin phong tỏa tạm thời. Nếu chứng minh được nợ lương, lần chuyển việc này không bị trừ vào hạn mức.',
        uz: "Hatto sud qarori boʻlsa ham, agar tortib olinadigan aktivlar boʻlmasa, undirish qiyin. Mehnat idorasi bosqichidan boshlab, biznes hisoblari, transport vositalari va mijozlarni tekshiring va agar aktivlar koʻchirilayotgan boʻlsa, vaqtinchalik xatlovni koʻrib chiqing. Agar toʻlanmagan ish haqi isbotlansa, bu oʻzgarish sizning ish joyi oʻzgarishi kvotangizga taʼsir qilmaydi.",
      ),
    ),
  ],
);
